                        rs.getString("trial_code"),
                        rs.getString("screening_no"),
                        rs.getString("visit_code"),
                        rs.getTimestamp("visit_time_utc").toInstant(),
                        rs.getBoolean("excluded_from_main_analysis")),
                trialCode, screeningNo);
    }
}

