        // 新 requestId 对已揭盲受试者再次请求：仍返回首次结果，不新增事件与审计。
        UnblindResponse replayByNewRequest = unblindingService.unblind("S-UB4",
                new UnblindRequest("UB-OTHER", DataSeeder.UNBLINDER_DR_WANG, DataSeeder.UNBLINDER_DR_LI));
